import{_ as i,l,o as e,c as n,v as r,p as s,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"PRAM 与前缀和","description":"","frontmatter":{"title":"PRAM 与前缀和","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pram-prefix-sum.md","filePath":"cs/pram-prefix-sum.md","lastUpdated":1789023840000}'),m={name:"cs/pram-prefix-sum.md"};function h(_,a,u,f,P,A){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="pram-与前缀和" tabindex="-1">PRAM 与前缀和 <a class="header-anchor" href="#pram-与前缀和" aria-label="Permalink to &quot;PRAM 与前缀和&quot;">​</a></h1><div class="epigraph"><p>共享内存并行：前缀和 $n$ 个数用 $O(\\log n)$ 时间、$O(n)$ 工作，是扫描、紧凑、链表的公共子程序。</p><footer>—— 据 Ladner and Fischer, Parallel Prefix Computation, 1980；JáJá, An Introduction to Parallel Algorithms 整理</footer></div><p>上一课<a href="/cs/external-memory-model">外存 I/O</a>是层次。PRAM：多处理器同步共享 RAM。缺口是前缀（scan）：\\(s_i=a_1+\\cdots+a_i\\)。串行 \\(O(n)\\)。并行：树上升下降 \\(O(\\log n)\\) 步。不重写 I/O 排序。后课 work-span。CREW/CRCW 点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平衡二叉树：内部点存区间和，再向下推前缀。工作 \\(O(n)\\)，跨度 \\(O(\\log n)\\)。链表前缀要用指针跳跃（Wyllie）或随机。CRCW 可更快但模型强。</p><p>缺口是前缀，不是 GPU 编程课。</p><h3 id="不是-mapreduce-语义" tabindex="-1">不是 MapReduce 语义 <a class="header-anchor" href="#不是-mapreduce-语义" aria-label="Permalink to &quot;不是 MapReduce 语义&quot;">​</a></h3><p>PRAM 同步共享内存。MapReduce 是数据并行另一模型。不要混。</p><p><span class="marginnote">Ladner–Fischer 1980。Blelloch scan。后课 work-span 把 PRAM 界翻译成 fork-join。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数组树两遍。应用：过滤（紧凑）、词法分析、括号匹配并行点名。</p>',11)),(e(),s(c,null,{default:o(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%20a_i%22%5D%20--%3E%20UP%5B%22%E6%A0%91%E4%B8%8A%E8%A1%8C%E6%B1%82%E5%92%8C%22%5D%0A%20%20UP%20--%3E%20DN%5B%22%E4%B8%8B%E8%A1%8C%E6%8E%A8%E5%89%8D%E7%BC%80%22%5D%0A%20%20DN%20--%3E%20S%5B%22s_i%20%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>结合律运算即可（\\(\\min\\)、\\(\\times\\)）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>区间结合律使树正确。工作 = 总运算，跨度 = 依赖长链。与快速幂：都是树形结合，一个并行一层、一个串行平方。与 FFT：蝶形也是 \\(\\log n\\) 层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 EREW 最优常数。不写 MPI 网络。后课默认：前缀和 \\(O(\\log n)\\) 跨度、\\(O(n)\\) 工作。下一课 work-span 与 fork-join。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀和是并行扫描原语。</li><li>\\(O(\\log n)\\) 时间、\\(O(n)\\) 工作。</li><li>结合律即可。</li><li>出处：Ladner and Fischer, 1980。</li></ul>',7))])}const B=i(m,[["render",h]]);export{x as __pageData,B as default};
